<?php require_once 'functions.php'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$q=$pdo->prepare('SELECT * FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch();if($u&&password_verify($pass,$u['password_hash'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];header('Location: '.app_url($u['role']==='admin'?'admin/index.php':'diagnosis.php'));exit;} $err='Email atau kata sandi tidak sesuai.';} header_html('Login');?><section class="auth card"><span class="eyebrow">SELAMAT DATANG KEMBALI</span><h1>Masuk ke KopiCare</h1><p class="muted">Simpan dan tinjau hasil diagnosis Anda.</p><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post" class="form"><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Kata sandi<input type="password" name="password" required autocomplete="current-password"></label><button class="button">Login</button></form><p>Belum punya akun? <a href="<?=e(app_url('register.php'))?>">Daftar</a></p></section><?php footer_html();?>
